'use client';
import { useState, useRef } from 'react';
import { Button } from './ui/button';
import { UploadCloud, FileText, CheckCircle, AlertCircle } from 'lucide-react';
import { cn } from '@/lib/utils';
import axios from 'axios';

interface FileUploadProps {
    onUploadStart: (jobId: string, count: number) => void;
    onError: (msg: string) => void;
}

export function FileUpload({ onUploadStart, onError }: FileUploadProps) {
    const [dragActive, setDragActive] = useState(false);
    const [file, setFile] = useState<File | null>(null);
    const [uploading, setUploading] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);

    const handleDrag = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setDragActive(true);
        } else if (e.type === "dragleave") {
            setDragActive(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            validateAndSetFile(e.dataTransfer.files[0]);
        }
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        e.preventDefault();
        if (e.target.files && e.target.files[0]) {
            validateAndSetFile(e.target.files[0]);
        }
    };

    const validateAndSetFile = (file: File) => {
        const validTypes = ['text/csv', 'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'text/plain'];
        // Naive type check, file extension is better
        if (file.name.endsWith('.csv') || file.name.endsWith('.xlsx')) { // || validTypes.includes(file.type)
            setFile(file);
        } else {
            onError("Please upload a CSV or Excel file.");
        }
    };

    const handleUpload = async () => {
        if (!file) return;
        setUploading(true);
        const formData = new FormData();
        formData.append('file', file);

        try {
            const res = await axios.post('http://localhost:3001/api/upload', formData, {
                headers: { 'Content-Type': 'multipart/form-data' }
            });
            onUploadStart(res.data.jobId, res.data.totalEmails);
            setFile(null);
        } catch (err: any) {
            console.error(err);
            onError(err.response?.data?.error || "Upload failed");
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="w-full max-w-xl mx-auto mb-10">
            <div
                className={cn(
                    "relative border-2 border-dashed rounded-xl p-10 transition-all text-center cursor-pointer",
                    dragActive ? "border-primary bg-primary/5 scale-[1.02]" : "border-slate-300 hover:border-primary/50",
                    file ? "bg-green-50/50 border-green-500/50" : "bg-white"
                )}
                onDragEnter={handleDrag}
                onDragLeave={handleDrag}
                onDragOver={handleDrag}
                onDrop={handleDrop}
                onClick={() => inputRef.current?.click()}
            >
                <input
                    ref={inputRef}
                    className="hidden"
                    type="file"
                    accept=".csv, .xlsx"
                    onChange={handleChange}
                />

                <div className="flex flex-col items-center gap-4 text-slate-600">
                    {file ? (
                        <>
                            <FileText className="w-12 h-12 text-green-500" />
                            <div className="text-lg font-semibold text-slate-900">{file.name}</div>
                            <div className="text-sm">{(file.size / 1024).toFixed(2)} KB</div>
                        </>
                    ) : (
                        <>
                            <UploadCloud className="w-16 h-16 text-primary/80" />
                            <div>
                                <span className="font-semibold text-primary">Click to upload</span> or drag and drop
                            </div>
                            <div className="text-sm text-slate-400">
                                CSV or Excel (Max 50MB)
                            </div>
                        </>
                    )}
                </div>
            </div>

            {file && (
                <div className="mt-4 flex justify-end">
                    <Button
                        onClick={handleUpload}
                        className="w-full md:w-auto"
                        disabled={uploading}
                    >
                        {uploading ? "Uploading..." : `Validate ${file.name}`}
                    </Button>
                </div>
            )}
        </div>
    );
}
